 private void creation(){page("Keep access after reinstalling","Save the encrypted file and keep its 24 words separately. Both together can decrypt saved chats. Restoring the account also needs your current app password and fingerprint or face unlock.");body.addView(Ui.button(this,"Before you create a backup",false,v->Ui.dialog(this).setTitle("Keep your recovery kit safe").setMessage("Anyone with the file and its 24 words can decrypt that snapshot offline. Your app password protects restoration on the server. Your account must still exist: deletion and self-destruct invalidate recovery. An older snapshot can contain messages deleted later.").setPositiveButton("Got it",null).show()));CheckBox chats=new CheckBox(this);chats.setText("Include saved chats");chats.setTextColor(getColor(R.color.ink));chats.setChecked(true);body.addView(chats);body.addView(Ui.button(this,"Create recovery backup",true,v->biometric.authenticate(()->password(pass->prepare(chats.isChecked(),pass)),this::error)));Repository.work(this,v->Repository.call(v,"getRecoveryStatus",new JSONObject()),state->{if(!alive())return;error(state.optBoolean("enabled")?"A recovery backup is active. Creating and activating a new one replaces it.":"No recovery backup is active yet.");},message->{if(alive())error("Recovery is unavailable until the service update is active.");});body.addView(Ui.button(this,"Revoke previous recovery backups",false,v->Ui.dialog(this).setTitle("Revoke recovery backups?").setMessage("Saved recovery files will no longer open this account. Your current installation stays signed in.").setNegativeButton("Cancel",null).setPositiveButton("Continue",(d,w)->biometric.authenticate(()->password(pass->run(vault->{try{Session.continueAccount(vault,null,new String(pass));Repository.call(vault,"revokeRecovery",new JSONObject());return true;}finally{Arrays.fill(pass,'\0');}},()->{creation();error("Previous recovery backups revoked.");})),this::error)).show()));}
