 private void prepare(boolean chats,char[] pass){model.busy=true;page("Making your recovery backup","Your recovery words are generated on this phone.");Repository.work(this,v->{try{if(!Objects.equals(owner,Session.uid()))throw new SecurityException("Sign in again.");return AccountRecovery.prepare(v,File.createTempFile("priperi-recovery-",".enc",getCacheDir()),chats,pass);}finally{Arrays.fill(pass,'\0');}},offer->{model.busy=false;if(model.closed){offer.close();return;}model.offer=offer;if(alive())offerPage(true);},message->{model.busy=false;Arrays.fill(pass,'\0');if(alive()){creation();error(message);}});}
